# Load all NPM packageinfo records
npm = pd.read_sql("SELECT Name, Version, VersionInfo FROM packageinfo WHERE System='NPM'", pkg_conn)
print(npm.shape)

# Parse VersionInfo
def parse_vi(s):
    try:
        d = json.loads(s)
        return d.get('IsRelease'), d.get('Ordinal')
    except Exception:
        return None, None

npm[['IsRelease', 'Ordinal']] = npm['VersionInfo'].apply(lambda s: pd.Series(parse_vi(s)))
print(npm.head())
print(npm['IsRelease'].value_counts(dropna=False))

# Build regex to extract slug (owner/repo) and stars from Project_Information

slug_patterns = [
    r'The project (?:named |titled )?([\w\-\._]+/[\w\-\._]+)',
    r'The GitHub project (?:named |titled )?([\w\-\._]+/[\w\-\._]+)',
    r'under the repository name ([\w\-\._]+/[\w\-\._]+)',
]

star_patterns = [
    r'([0-9,]+)\s+stars?\b',
    r'stars count of ([0-9,]+)',
    r'star count of ([0-9,]+)',
]

def extract_slug(text):
    if not isinstance(text, str):
        return None
    for p in slug_patterns:
        m = re.search(p, text)
        if m:
            return m.group(1)
    return None

def extract_stars(text):
    if not isinstance(text, str):
        return None
    for p in star_patterns:
        m = re.search(p, text)
        if m:
            try:
                return int(m.group(1).replace(',', ''))
            except Exception:
                return None
    return None

pi['Slug'] = pi['Project_Information'].apply(extract_slug)
pi['Stars'] = pi['Project_Information'].apply(extract_stars)

print("Total rows:", len(pi))
print("Slug parsed:", pi['Slug'].notna().sum())
print("Stars parsed:", pi['Stars'].notna().sum())
print(pi[pi['Slug'].isna()].head(10)['Project_Information'].tolist())
print(pi[pi['Stars'].isna()].head(10)['Project_Information'].tolist())
